import{z as p,x as B,o as l,c as d,q as n,j as o,D as t,d as r,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"操作语义：进展与保持","description":"","frontmatter":{"title":"操作语义：进展与保持","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/operational-semantics.md","filePath":"cs/operational-semantics.md","lastUpdated":1791063341000}'),A={name:"cs/operational-semantics.md"};function m(C,a,h,u,S,c){const s=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=n('<h1 id="操作语义-进展与保持" tabindex="-1">操作语义：进展与保持 <a class="header-anchor" href="#操作语义-进展与保持" aria-label="Permalink to &quot;操作语义：进展与保持&quot;">​</a></h1><div class="epigraph"><p>小步：一次改写一项。大步：直接给值。上下文指出下一归约点。类型定理建立在这份关系上，而不是建立在编译器实现上。</p><footer>—— 据 Plotkin, A Structural Approach to Operational Semantics；Pierce TAPL；Wright and Felleisen, 1994 整理</footer></div><p>上一课<a href="/cs/type-soundness">类型健全性</a>已经调用了「一步」与「值」。缺口是把<strong>操作语义</strong>写清楚：小步 SOS、求值上下文、调用约定（值调用 vs 名调用）如何改变进展陈述。不重写 λ 的 β 定义，只把它收成关系 \\(t \\to t&#39;\\)。也不写指称——下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「程序做什么」若只靠编译器，无法证保持。<a href="/cs/lambda-calculus">λ 演算</a>有 β；STLC 要规定应用序还是正规序。小步：\\(\\mathrm{E}[(\\lambda x.t)\\,v] \\to \\mathrm{E}[t[v/x]]\\)。大步：\\(\\langle t,\\sigma\\rangle \\Downarrow v\\)。缺口是<strong>关系与上下文</strong>，不是 lex。</p><p>状态：引用语言要堆 \\(\\sigma\\)。进展变成：良型配置或能一步，或已是值。并发：一步是线程交错，保持更难。</p><h3 id="小步不是「解释器源码」" tabindex="-1">小步不是「解释器源码」 <a class="header-anchor" href="#小步不是「解释器源码」" aria-label="Permalink to &quot;小步不是「解释器源码」&quot;">​</a></h3><p>SOS 是数学关系。定义式解释器（Reynolds）是函数，可作可执行规范，但仍要与 SOS 对齐。本课以 SOS 为主。</p><p><span class="marginnote">Plotkin SOS。Felleisen 的求值上下文。Pierce TAPL 贯穿小步。Appel 的编译器正确性用语义对齐。本课不写 CompCert 的 Clight，那在课程末尾。</span></p><p><span class="marginnote">术语翻译：CBV（值调用）就是先把参数算成值再代入函数体——C、Java、Python 都是这个脾气；CBN（名调用）是把参数表达式原封不动代入，用到才算。同一个程序在两种策略下，求值路径甚至会不会停机都可能不同，所以「选策略」就是选规则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列出语法、值、一步规则。选策略：CBN/CBV 改变哪条规则。证明：同一套进展保持。实现对照：字节码解释器应仿真小步（运行时单元）。</p>',12)),(l(),o(E,null,{default:t(()=>[i(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%A1%B9%22%5D%20--%3E%20CTX%5B%22%E6%B1%82%E5%80%BC%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20CTX%20--%3E%20STEP%5B%22%E5%B0%8F%E6%AD%A5%20%E2%86%92%22%5D%0A%20%20STEP%20--%3E%20V%5B%22%E5%80%BC%E6%88%96%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：求值上下文 \\(\\mathrm{E}[\\,\\square\\,]\\) 像一张「带洞的模板」，洞里填什么（哪个子项），哪里就是下一步的归约点——相当于把「先找位置、再改写」拆成填空题，规则就不用为每种嵌套写一遍。")],-1)),a[4]||(a[4]=e("p",null,"与效应：一步可带事件标签，得带标签的转换系统，供效应类型解释。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"合流：无类型 λ 有；加状态后一般没有「同一值」的合流，只有类型保证的不卡住。不要用 Church–Rosser 当命令式语言的健全性。",-1)),a[7]||(a[7]=e("p",null,"大步对不终止无推导，难以谈进展；小步更适合卡住分析。大步适合证明编译器「若源停机则目标得相同值」。",-1)),a[8]||(a[8]=e("p",null,"小步与大步各自适合回答什么问题：",-1)),(l(),o(E,null,{default:t(()=>[i(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E9%A1%B9%20t%22%5D%20--%3E%7C%22%E5%B0%8F%E6%AD%A5%3A%20%E6%AF%8F%E6%AC%A1%E6%94%B9%E5%86%99%E4%B8%80%E9%A1%B9%22%7C%20S1%5B%22t1%20%E2%86%92%20t2%20%E2%86%92%20t3%20%E2%86%92%20%E2%80%A6%22%5D%0A%20%20S1%20--%3E%7C%22%E7%9C%8B%E5%BE%97%E8%A7%81%E6%AF%8F%E4%B8%80%E6%AD%A5%E4%B8%AD%E9%97%B4%E6%80%81%22%7C%20G1%5B%22%E5%8F%AF%E5%88%86%E6%9E%90%E5%8D%A1%E4%BD%8F%3A%20%E8%AF%81%E8%BF%9B%E5%B1%95%22%5D%0A%20%20T%20--%3E%7C%22%E5%A4%A7%E6%AD%A5%3A%20%E7%9B%B4%E6%8E%A5%E7%BB%99%E5%80%BC%22%7C%20B1%5B%22t%20%E2%87%93%20v%22%5D%0A%20%20B1%20--%3E%7C%22%E5%8F%AA%E6%9C%89%E8%B5%B7%E7%82%B9%E4%B8%8E%E7%BB%88%E7%82%B9%22%7C%20G2%5B%22%E9%80%82%E5%90%88%E8%AF%81%E5%81%9C%E6%9C%BA%E5%88%99%E7%AD%89%E5%80%BC%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=n('<p><span class="marginnote">数字实例：把死循环 \\(\\Omega\\) 当参数传给 \\(\\lambda x.\\,3\\)——CBV 先算参数，永不停止；CBN 不算参数，一步得到 \\(3\\)。一个「参数根本没被用到」的例子，就能看出策略选择改变的是可停机性，不只是快慢。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写抽象机器（SECD、CEK）的全部转移。后课默认：类型定理相对 SOS。下一课指称语义：用数学对象解释项，对照操作。</p><p>也不把 CPU 流水线当操作语义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>小步/大步是项（加状态）上的关系。</li><li>进展保持建立在小步上更自然。</li><li>策略（CBV/CBN）是规则选择。</li><li>出处：Plotkin；Felleisen；Pierce TAPL；Wright–Felleisen。</li></ul>',6))])}const P=p(A,[["render",m]]);export{D as __pageData,P as default};
